		/* common.mdsr.updateMasterMdSrSrProcWritePop */
			UPDATE KEPASRDT SET
				CD_DATE=TO_DATE(TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS'), 'YYYYMMDDHH24MISS'),
				CD_USER_ID=#{st_user_id},
				DS_REMARK=#{st_ds_remark},
				DS_DATE=TO_DATE(REPLACE(#{st_ds_date}, '/')||#{st_ds_time}, 'YYYYMMDDHH24MISS'),
				RECV_FLAG='DS'
			WHERE USER_ID=#{st_sr_user_id}    
               AND SR_NO=#{st_sr_no}
